package io.github.polestarcn.companion;
import android.content.Context;import android.os.Bundle;import java.util.Locale;
/** Consolidated real state for the ColorOS vehicle-provider UI. Digital-key state is never inferred. */
final class OppoSystemVehicleState {
  private OppoSystemVehicleState(){}
  static Bundle status(Context context,VehicleCoordinator coordinator){Bundle out=new Bundle();Bundle bind=OppoOfficialVehicleBindState.status(context,coordinator);Bundle assistant=OppoAssistantHostDiagnostics.status(context);Bundle account=OppoAccountBindDiagnostics.status(context);Bundle carlink=OppoOfficialCarLink.status(context);Bundle carlinkHost=OppoCarLinkHostDiagnostics.status(context);Bundle key=OppoCarKeyCapability.status(context);
    boolean signedIn=bind.getBoolean("signedIn",false),vehicle=bind.getBoolean("vehicleAvailable",false),requested=bind.getBoolean("requested",false);String catalog=account.getString("providerCatalog","");
    out.putString("providerCode","POLESTAR");out.putBoolean("signedIn",signedIn);out.putBoolean("vehicleAvailable",vehicle);out.putBoolean("remoteControlAvailable",signedIn&&vehicle);out.putBoolean("providerRequested",requested);out.putBoolean("providerEnabled",bind.getBoolean("enabled",false));out.putBoolean("assistantHookSeen",assistant.getLong("seenAt",0L)>0);out.putString("assistantVersion",assistant.getString("hostVersion",""));out.putBoolean("providerCatalogContainsPolestar",catalog.toUpperCase(Locale.ROOT).contains("POLESTAR"));out.putBoolean("carLinkInstalled",carlink.getBoolean("installed",false));out.putBoolean("carLinkServiceAvailable",carlink.getBoolean("serviceAvailable",false));out.putString("carLinkVersion",carlink.getString("versionName",""));out.putBoolean("carLinkHostHookSeen",carlinkHost.getLong("seenAt",0L)>0);out.putBoolean("oppoBluetoothKeySupported",key.getBoolean("bindSurfaceAvailable",false));
    // No current project signal proves a real PAK pairing or OPPO key registration. Keep them unknown/false.
    Bundle shelf=OppoShelfCardCapability.status(context);out.putBoolean("shelfCardHostVisible",shelf.getBoolean("cardHostVisible",false));out.putBoolean("shelfCardMetadataReady",shelf.getBoolean("shelfMetadataReady",false));out.putBoolean("shelfCardPantanalHookSeen",shelf.getBoolean("pantanalHookSeen",false));out.putBoolean("cardWidgetRuntimeSupported",shelf.getBoolean("cardWidgetRuntimeSupported",false));out.putString("cardWidgetUiEngineVersion",shelf.getString("uiEngineVersion",""));out.putBoolean("providerEntryReady",bind.getBoolean("enabled",false)&&catalog.toUpperCase(Locale.ROOT).contains("POLESTAR"));
    out.putBoolean("pakStateKnown",false);out.putBoolean("polestarPakPaired",false);out.putBoolean("oppoKeyStateKnown",false);out.putBoolean("oppoKeyRegistered",false);return out;}
}